@Injectable()
export class LoggerMiddleware
        implements NestMiddleware {

    use(
        request: Request,
        response: Response,
        next: NextFunction
    ) {
        console.log(
            request.method,
            request.url
        );

        next();
    }
}

@Injectable()
export class AuthGuard
        implements CanActivate {

    canActivate(
        context: ExecutionContext
    ): boolean {
        const request =
            context
                .switchToHttp()
                .getRequest();

        return Boolean(
            request.user
        );
    }
}

@Get(":id")
getUser(
    @Param(
        "id",
        ParseIntPipe
    )
    id: number
) {
    return this.usersService
        .getUser(id);
}

